"1231 :   private void visitGetProp(NodeTraversal t, Node n, Node parent) {
1232 :     // GETPROP nodes have an assigned type on their node by the scope creator
1233 :     // if this is an enum declaration. The only namespaced enum declarations
1234 :     // that we allow are of the form object.name = ...;
1235 :     if (n.getJSType() != null && parent.getType() == Token.ASSIGN) {
1236 :       return;
1237 :     }
1238 : 
1239 :     // obj.prop or obj.method()
1240 :     // Lots of types can appear on the left, a call to a void function can
1241 :     // never be on the left. getPropertyType will decide what is acceptable
1242 :     // and what isn't.
1243 :     Node property = n.getLastChild();
1244 :     Node objNode = n.getFirstChild();
1245 :     JSType childType = getJSType(objNode);
1246 : 
1247 :     // TODO(user): remove in favor of flagging every property access on
1248 :     // non-object.
1249 :     if (!validator.expectNotNullOrUndefined(t, n, childType,
1250 :             childType + " has no properties", getNativeType(OBJECT_TYPE))) {
1251 :       ensureTyped(t, n);
1252 :       return;
1253 :     }
1254 : 
1255 :     checkPropertyAccess(childType, property.getString(), t, n);
1256 :     ensureTyped(t, n);
1257 :   }"

"1262 :   private void checkPropertyAccess(JSType childType, String propName,
1263 :       NodeTraversal t, Node n) {
1264 :     ObjectType objectType = childType.dereference();
1265 :     if (objectType != null) {
1266 :       JSType propType = getJSType(n);
1267 :       if ((!objectType.hasProperty(propName) ||
1268 :            objectType.equals(typeRegistry.getNativeType(UNKNOWN_TYPE))) &&
1269 :           propType.equals(typeRegistry.getNativeType(UNKNOWN_TYPE))) {
1270 :         if (objectType instanceof EnumType) {
1271 :           report(t, n, INEXISTENT_ENUM_ELEMENT, propName);
1272 :         } else if (!objectType.isEmptyType() &&
1273 :             reportMissingProperties && !isPropertyTest(n)) {
1274 :           if (!typeRegistry.canPropertyBeDefined(objectType, propName)) {
1275 :             report(t, n, INEXISTENT_PROPERTY, propName,
1276 :                 validator.getReadableJSTypeName(n.getFirstChild(), true));
1277 :           }
1278 :         }
1279 :       }
1280 :     } else {
1281 :       // TODO(nicksantos): might want to flag the access on a non object when
1282 :       // it's impossible to get a property from this type.
1283 :     }
1284 :   }"

